INSERT INTO `homecontent` (`id`, `promoCards`, `teamMembers`, `hochHinausHtml`, `updatedAt`, `newsEyebrow`, `newsTitle`, `hochHinausEyebrowPrefix`, `hochHinausEyebrowLinkText`, `hochHinausTitle`, `teamLink`) VALUES
('default', '[{\"title\":\"Fliegen Lernen\",\"boldLine\":\"Der Anfang einer neuen Leidenschaft!\",\"description\":\"Reinschnuppern beim 1-Tageskurs oder Schnupperwochenende\",\"image\":\"/images/startbuttons/startbutton_schnuppern.jpg\",\"link\":\"/ausbildung/schnupperkurs\"},{\"title\":\"Shop Geöffnet\",\"boldLine\":\"Mittwoch, 2.9.26 16-19 Uhr\",\"description\":\"Alex und Sarah sind für euch in Weinheim im Laden, bitte unbedingt voranmelden!\",\"image\":\"/images/startbuttons/gutschein.jpg\",\"link\":\"/infos\"},{\"title\":\"On Tour...\",\"boldLine\":\"23.1. - 6.2.2027 | Kolumbien\",\"description\":\"Fliegen über den grünen Landschaften des Valle del Cauca in den besten Fluggebieten von Cali Richtung Medellin...\",\"image\":\"/images/bilder/2-tour-kolumbien/Kolumbien_3997_2.jpg\",\"link\":\"/reisen/kolumbien-tour\"}]', '[{\"name\":\"Alex\",\"image\":\"/images/team/schlink.jpg\"},{\"name\":\"Sarah\",\"image\":\"/images/team/sarah.jpg\"},{\"name\":\"Tobi\",\"image\":\"/images/team/tobi.jpg\"},{\"name\":\"Holger\",\"image\":\"/images/team/holger.jpg\"},{\"name\":\"Markus\",\"image\":\"/images/team/markus.jpg\"}]', '<p>Willkommen bei der Flugschule Hirondelle, der Gleitschirmschule im Rhein-Main-Neckar Dreieck. Fliegen lernen mit dem <a href=\"/infos/team\">Team Hirondelle</a> heißt: Persönliche und individuelle auf den Schüler zugeschnittene Ausbildung. Unser Team besteht aus sehr erfahrenen und ambitionierten Fluglehrern.</p><p>Alles natürlich an genialen Schulungshängen im Raum Odenwald, Kraichtal, Nahetal und in der Pfalz.</p>', '2026-09-21 06:23:31.474', 'AKTUELLES', 'NEWS', '...mit dem', 'Team Hirondelle', 'HOCH HINAUS', '/infos/team');
